<?php
session_start(); require_once __DIR__.'/dbconnection.php';
if(($_SESSION['portal_role']??'')!=='patient' || !isset($_SESSION['patientid'])){http_response_code(403);exit('Access denied');}
$id=(int)$_SESSION['patientid'];
$p=$con->prepare("SELECT * FROM patient WHERE patientid=? LIMIT 1");$p->bind_param('i',$id);$p->execute();$patient=$p->get_result()->fetch_assoc();
$t=$con->prepare("SELECT tr.treatment_date,tr.treatment_description,tr.uploads,d.doctorname,ap.appointmentdate,ap.appointmenttime FROM treatment_records tr LEFT JOIN doctor d ON d.doctorid=tr.doctorid LEFT JOIN appointment ap ON ap.appointmentid=tr.appointmentid WHERE tr.patientid=? ORDER BY tr.treatment_date DESC");$t->bind_param('i',$id);$t->execute();$treatments=$t->get_result();
$pr=$con->prepare("SELECT p.prescriptiondate,p.status,d.doctorname,pr.medicine_name,pr.dosage,pr.unit FROM prescription p LEFT JOIN doctor d ON d.doctorid=p.doctorid LEFT JOIN prescription_records pr ON pr.prescription_id=p.prescriptionid WHERE p.patientid=? ORDER BY p.prescriptiondate DESC");$pr->bind_param('i',$id);$pr->execute();$prescriptions=$pr->get_result();
?><!doctype html><html><head><meta charset="utf-8"><title>My Health</title><link rel="stylesheet" href="professional_assets/app.css"><link rel="stylesheet" href="professional_assets/theme.css.php"></head><body class="module-body"><div class="module-card"><h1>My Health Record</h1><div class="health-grid"><div><b>Patient</b><p><?php echo htmlspecialchars($patient['patientname']);?></p></div><div><b>Blood group</b><p><?php echo htmlspecialchars($patient['bloodgroup']);?></p></div><div><b>Gender</b><p><?php echo htmlspecialchars($patient['gender']);?></p></div><div><b>Date of birth</b><p><?php echo htmlspecialchars($patient['dob']);?></p></div></div><h2>Diagnoses & Treatments</h2><?php if(!$treatments->num_rows):?><p class="muted">No treatment records yet.</p><?php else: while($r=$treatments->fetch_assoc()):?><div class="record"><b><?php echo htmlspecialchars($r['treatment_date']);?> · <?php echo htmlspecialchars($r['doctorname']??'Doctor');?></b><p><?php echo nl2br(htmlspecialchars($r['treatment_description']));?></p></div><?php endwhile; endif;?><h2>Prescriptions</h2><?php if(!$prescriptions->num_rows):?><p class="muted">No prescriptions yet.</p><?php else: while($r=$prescriptions->fetch_assoc()):?><div class="record"><b><?php echo htmlspecialchars($r['prescriptiondate']);?> · <?php echo htmlspecialchars($r['doctorname']??'Doctor');?></b><p><?php echo htmlspecialchars($r['medicine_name']??''); ?> — <?php echo htmlspecialchars($r['dosage']??'');?> — <?php echo (int)($r['unit']??0);?></p></div><?php endwhile; endif;?></div></body></html>
